/*
f(S) = min({x_i for i ∈ S}) where S ⊂ V
                    g(S) = max({x_i for i ∈ S}) where S ⊂ V
                    z = 1
                    where
                    V ∈ {ℤ}
                    x_i ∈ ℝ
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    int z;
    std::vector<int > V;
    std::vector<double> x;
    double f(
        const std::vector<int > & S)
    {
        std::vector<double > fset_0;
        const std::vector<int >& range = S;
        fset_0.reserve(range.size());
        for(int i : range){
            fset_0.push_back(this->x.at(i-1));
        }
        if(fset_0.size() > 1){
            sort(fset_0.begin(), fset_0.end());
            fset_0.erase(unique(fset_0.begin(), fset_0.end() ), fset_0.end());
        }
        return *(fset_0).begin();    
    }
    double g(
        const std::vector<int > & S)
    {
        std::vector<double > gset_0;
        const std::vector<int >& range_1 = S;
        gset_0.reserve(range_1.size());
        for(int i : range_1){
            gset_0.push_back(this->x.at(i-1));
        }
        if(gset_0.size() > 1){
            sort(gset_0.begin(), gset_0.end());
            gset_0.erase(unique(gset_0.begin(), gset_0.end() ), gset_0.end());
        }
        return *(gset_0).rbegin();    
    }
    heartlib(
        const std::vector<int > & V,
        const std::vector<double> & x)
    {
        const long dim_0 = x.size();
        this->V = V;
        this->x = x;
        // z = 1
        z = 1;
    }
};

