function output = heartlib(V, x)
% output = heartlib(V, x)
%
%    f(S) = min({x_i for i ∈ S}) where S ⊂ V
%                        g(S) = max({x_i for i ∈ S}) where S ⊂ V
%                        z = 1
%                        where
%                        V ∈ {ℤ}
%                        x_i ∈ ℝ
    x = reshape(x,[],1);

    dim_0 = size(x, 1);
    assert( size(x,1) == dim_0 );

    % z = 1

    z = 1;
    function [ret] = f(S)
        fset_0 = [];
        range = S;
        for index = 1:length(range)
            i = range(index);
            fset_0 = [fset_0; x(i)];
        end
        ret = min(fset_0);
    end

    function [ret_1] = g(S)
        gset_0 = [];
        range_1 = S;
        for index_1 = 1:length(range_1)
            i = range_1(index_1);
            gset_0 = [gset_0; x(i)];
        end
        ret_1 = max(gset_0);
    end

    output.z = z;
    output.f = @f;
    output.g = @g;
    output.V = V;    
    output.x = x;
end

